def N(l,a,u,w,t=None):return dict(label=l,type='numeric',answer=float(a),unit=u,tolerance=max(abs(a)*.008,1e-25) if t is None else t,explanation=w)
def C(l,a,b,c,w):return dict(label=l,type='choice',answer=a,options=[a,b,c],explanation=w)
def R(n,ps,w,kind='problems',pages=None,scope=None,ass=None):
 page=(25 if n<=13 else 26 if n<=28 else 27 if n<=38 else 28 if n<=52 else 29 if n<=65 else 30 if n<=76 else 31 if n<=93 else 32) if kind=='problems' else(23 if n<=4 else 24)
 r=dict(id=f'physics-chapter-27-{kind}-{n}',parts=ps,reasoning=w+' Verification: substitute the calculated currents into junction and loop equations; check electrical power or the stated RC initial/final limits.',sourcePages=pages or [page],assumptions=ass or ['Ideal batteries and wires except for explicitly stated internal or meter resistance.'])
 if scope:r['scope']=scope
 rows.append(r)
def par(*rs):return 1/sum(1/r for r in rs)
def nodal(fixed,edges):
 names=sorted(set(sum(([a,b] for a,b,r in edges),[]))-set(fixed));A=np.zeros((len(names),len(names)));B=np.zeros(len(names));idx={n:i for i,n in enumerate(names)}
 for a,b,r in edges:
  for x,y in [(a,b),(b,a)]:
   if x in idx:
    i=idx[x];A[i,i]+=1/r
    if y in idx:A[i,idx[y]]-=1/r
    else:B[i]+=fixed[y]/r
 v={**fixed,**dict(zip(names,np.linalg.solve(A,B)))}
 assert all(abs(sum((v[x]-v[b if a==x else a])/r for a,b,r in edges if a==x or b==x))<1e-8 for x in names)
 return v
