# Independently enumerate normalized series/parallel networks for the minimum-count power problem.
from fractions import Fraction
networks={1:{Fraction(1):Fraction(1)}}
for count in range(2,10):
 best={}
 for left in range(1,count):
  for a,pa in networks[left].items():
   for b,pb in networks[count-left].items():
    for r,power in [(a+b,max(pa*(a/(a+b))**2,pb*(b/(a+b))**2)),(a*b/(a+b),max(pa,pb))]:
     if r not in best or power<best[r]:best[r]=power
 networks[count]=best
assert all(networks[n].get(Fraction(1),Fraction(1))>Fraction(1,5) for n in range(1,9))
assert networks[9][Fraction(1)]==Fraction(1,9)
