 for a,b in {'morecurrent':'more current','remainsthe':'remains the','no steady':'no steady','straightline':'straight line','leftward.':'leftward.','belowground':'below ground','capacitor’s':'capacitor’s','positiveleft':'positive left','lowernode':'lower node','uppersource':'upper source','sourcepositive':'source positive','battery1supplies':'battery 1 supplies','uppernode':'upper node','bottomleft':'bottom left','rightnode':'right node','lefttop':'left top','leftbottom':'left bottom','toprail':'top rail','lowerrail':'lower rail','leftrow':'left row','Rtop':'R top','Rbottom':'R bottom','micro-unit':'micro-unit'}.items():s=s.replace(a,b)
 return s
